### Design your prompt here
def restaurant_data_structure_prompt_generation(restaurant_paragraph):
    base_system_msg = f"""
    You are an restaurant specialized assistant , your work is to convert plain text descriptions from restaurants into a well structured
    format JSON using the following fields:
    {{
        "name": "",
        "location": "",
        "type": "",
        "food_style": "",
        "rating": 0.0,
        "price_range": 0,
        "signatures": [],
        "vibe": "",
        "environment": "",
        "shortcomings": []
    }}
    """
    
    base_user_prompt = f"""
    Task:
    Extract the restaurant information below and return it as a format JSON like the one's from the example above. Don't invent any data.
    If a field is not mentioned in the description, use null (or an empty list for signatures/shortcomings). Do not infer or guess missing information.

    Restaurant description:
    {restaurant_paragraph}

    Example:
    Input Restaurant Description: {EXAMPLE_RESTAURANT_PARAGRAPH}
    Output:
    {EXAMPLE_OUTPUT}
    """
    return base_system_msg, base_user_prompt


