# Validation
from pydantic import BaseModel, Field, ValidationError
from typing import List, Optional

### 3.1. Define the schema
class Restaurant(BaseModel):
    name: str
    location: str
    type: str
    food_style: str
    rating: Optional[float] = None
    price_range: Optional[int] = None
    signatures: List[str] = Field(default_factory=list)
    vibe: Optional[str] = None
    environment: str
    shortcomings: List[str] = Field(default_factory=list)


### 3.2. Use the validation method to validate the test_response from the unit test
try:
    restaurant_data = Restaurant.model_validate_json(test_response)
    print(f"Success! Validated: {restaurant_data.name}")
except ValidationError as e:
    print(f"Validation failed: {e.json()}")


def JSON_auto_repair_prompts(candidate_json_output, error_message):
    auto_repair_system_msg = """
    Eres un asistente especializado en corregir JSON mal formado según un esquema específico. 
    Se te dará un JSON con errores y el mensaje de error de validación. 
    Tu trabajo es corregir el JSON para que cumpla el esquema, sin cambiar la información real que ya contiene.
    """
    auto_repair_prompt = f"""
    Task: El siguiente JSON no pasó la validación. Corrígelo basándote en el error indicado.

    JSON con errores:
    {candidate_json_output}

    Error de validación:
    {error_message}

    Devuelve únicamente el JSON corregido, sin explicaciones adicionales.
    """
    return auto_repair_system_msg, auto_repair_prompt


### 2.3: Process the entire restaurant list with validation and auto-correction
structured_restaurant_lists = []
for idx, restaurant_paragraph in enumerate(restaurant_list):
    ### 2.1: Produce your initial output
    base_system_msg, base_user_prompt = restaurant_data_structure_prompt_generation(restaurant_paragraph)
    candidate_json_output = safe_llm_call(system_msg=base_system_msg, prompt_txt=base_user_prompt)

    ### 2.2: Validation and Auto Correction loop on the output 
    retry_count = 0
    while retry_count < 10:
        try:
            restaurant_data = Restaurant.model_validate_json(candidate_json_output)
            print(f"Success! Validated: {restaurant_data.name}")
            break
        except ValidationError as e:
            msg_error = e.json()
            new_system_msg_rep, new_prompt_repaired = JSON_auto_repair_prompts(candidate_json_output, msg_error)
            new_test_response = safe_llm_call(system_msg=new_system_msg_rep, prompt_txt=new_prompt_repaired)
            candidate_json_output = new_test_response
            retry_count += 1

    ### 2.3: Append your finalized response to the structured_restaurant_lists
    structured_restaurant_lists.append(restaurant_data)

    # A manual progress bar
    if (idx + 1) % 20 == 0:
        print(f'{idx + 1} out of {len(restaurant_list)} is done')

# A final message to notify the completion
print('ALL DONE!!')


